measurementDriver:
import * as fs from "node:fs/promises";
import * as path from "node:path";
import * as vcs from "/home/ken/Projects/pi-forge/packages/natives/native/vcs.js";
import { linkRepositoryDependencies, runSystem } from "/home/ken/Projects/pi-forge/packages/coding-agent/bench/task-outcome-ab.ts";
import type { PacketManifest } from "/home/ken/Projects/pi-forge/packages/coding-agent/bench/task-outcome-ab.ts";

const repo = "/home/ken/Projects/pi-forge";
const output = "/tmp/pi-forge-edit-measurements";
const runtime = path.join(output, "runtime");
const source = vcs.requireGit(repo);
const revision = await source.resolveRef("HEAD");
if (!revision) throw new Error("Missing runtime revision");
await source.worktreeAdd(runtime, revision, { detach: true, clone: false });
await linkRepositoryDependencies(repo, runtime);
await Bun.write(path.join(runtime, "packages/coding-agent/src/export/html/tool-views.generated.js"), Bun.file(path.join(repo, "packages/coding-agent/src/export/html/tool-views.generated.js")));
for (const name of await fs.readdir(path.join(repo, "packages/natives/native"))) {
	if (name.endsWith(".node")) await Bun.write(path.join(runtime, "packages/natives/native", name), Bun.file(path.join(repo, "packages/natives/native", name)));
}
const original = await Bun.file(path.join(runtime, "crates/pi-edit/prompts/hashline.md")).text();
const revised = await Bun.file(path.join(repo, "crates/pi-edit/prompts/hashline.md")).text();
const indexFile = path.join(runtime, "packages/coding-agent/src/edit/index.ts");
let index = await Bun.file(indexFile).text();
const branch = ": editDescription(mode);";
if (!index.includes(branch)) throw new Error("Cannot install isolated prompt delivery adapter");
index = 'import experimentPrompt from "./measurement-prompt.md" with { type: "text" };\n' + index.replace(branch, ': (mode === "hashline" ? experimentPrompt : editDescription(mode));');
await Bun.write(indexFile, index);
const packet = path.join(repo, "packages/coding-agent/bench/fixtures/governor-repository-maintenance-v1");
const manifest: PacketManifest = await Bun.file(path.join(packet, "manifest.json")).json();
const digest = async (text: string): Promise<string> => Buffer.from(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text))).toString("hex");
const addon = path.join(runtime, "packages/natives/native/pi_natives.linux-x64-modern.node");
const metadata = {
	runtimeRevision: revision,
	runtimeAdapter: "Both conditions use the same static MD adapter for hashline descriptions, with the same rebuilt native addon and CLI. Only the delivered full edit prompt differs; compact prompt policy is unchanged.",
	model: "openai-codex/gpt-6-luna", thinking: "low", adaptiveMode: "auto", budget: "unbounded", repeatCount: 1,
	originalPrompt: original, revisedPrompt: revised,
	originalPromptSha256: await digest(original), revisedPromptSha256: await digest(revised),
	addonSha256: Buffer.from(await crypto.subtle.digest("SHA-256", await Bun.file(addon).arrayBuffer())).toString("hex"),
	packet: manifest,
	packetSha256: {} as Record<string, string>,
};
for await (const file of new Bun.Glob("*").scan({ cwd: packet, onlyFiles: true })) metadata.packetSha256[file] = await digest(await Bun.file(path.join(packet, file)).text());
await Bun.write(path.join(output, "metadata.json"), JSON.stringify(metadata, null, 2));
try {
	for (const [condition, content] of [["original", original], ["revised", revised]] as const) {
		await Bun.write(path.join(runtime, "packages/coding-agent/src/edit/measurement-prompt.md"), content);
		const verify = Bun.spawn([process.execPath, "-e", 'import {resolveEditToolDescription} from "./packages/coding-agent/src/edit/index.ts"; process.stdout.write(resolveEditToolDescription("hashline", undefined));'], { cwd: runtime, stdout: "pipe", stderr: "pipe" });
		const delivered = await new Response(verify.stdout).text();
		const error = await new Response(verify.stderr).text();
		if (await verify.exited !== 0 || delivered !== content.trimEnd()) throw new Error(`Prompt delivery mismatch: ${error}`);
		const boot = Bun.spawn([process.execPath, path.join(runtime, "packages/coding-agent/src/cli.ts"), "--help"], { cwd: runtime, stdout: "ignore", stderr: "pipe" });
		const bootError = await new Response(boot.stderr).text();
		if (await boot.exited !== 0) throw new Error(`CLI startup failed before provider request: ${bootError}`);
		const out = path.join(output, condition);
		await fs.mkdir(out, { recursive: true });
		console.log(`Starting ${condition}: Luna Low, auto, seven fixed checks, unbounded`);
		const result = await runSystem("piforge", path.join(runtime, "packages/coding-agent/src/cli.ts"), metadata.model, packet, manifest, out, 1, new Map(), repo, "auto", null, "low");
		await Bun.write(path.join(out, "summary.json"), JSON.stringify(result, null, 2));
		console.log(JSON.stringify({ condition, passed: result.passed, tokens: result.totalTokens, costUsd: result.costUsd, wallTimeMs: result.wallTimeMs }));
	}
} finally {
	await source.worktreeRemove(runtime, true);
}
